.exRow{display:flex;gap:12px;padding:0 4vw;height:clamp(460px,64vh,620px)}
.exC{position:relative;flex:1 1 0;min-width:0;overflow:hidden;border-radius:18px;border:1px solid rgba(244,243,239,.12);background:#0F0F10;cursor:pointer;isolation:isolate;transition:flex-grow .7s cubic-bezier(.2,.7,0,1),border-color .4s,box-shadow .4s}
.exC.on{flex-grow:3.4;border-color:rgba(241,158,101,.7);box-shadow:0 0 0 1px rgba(241,158,101,.25),0 24px 70px rgba(0,0,0,.45),0 0 50px rgba(241,158,101,.12);cursor:default}
.exC:focus-visible{outline:2px solid #F19E65;outline-offset:3px}
.exBg{position:absolute;inset:0;z-index:-2;background-size:cover;filter:saturate(.9) brightness(.8);transform:scale(1.04);transition:transform 1s cubic-bezier(.2,.7,0,1),filter .6s}
.exC.on .exBg{transform:scale(1);filter:saturate(1) brightness(1)}
.exC::after{content:'';position:absolute;inset:0;z-index:-1;background:linear-gradient(180deg,rgba(10,10,11,.35) 0%,rgba(10,10,11,.05) 30%,rgba(10,10,11,.75) 62%,rgba(10,10,11,.97) 100%);transition:background .6s}
.exC.on::after{background:linear-gradient(90deg,rgba(10,10,11,.92) 0%,rgba(10,10,11,.6) 38%,rgba(10,10,11,0) 70%),linear-gradient(0deg,rgba(10,10,11,.5) 0%,rgba(10,10,11,0) 40%)}
.exN{position:absolute;left:22px;top:20px;font-size:13px;letter-spacing:.14em;color:#F19E65}
.exBody{position:absolute;left:18px;right:16px;bottom:24px;display:flex;flex-direction:column;gap:14px}
.exBody h3{margin:0;font-size:clamp(18px,1.35vw,22px);line-height:1.15;font-weight:500;letter-spacing:-.015em;text-shadow:0 2px 14px rgba(0,0,0,.8);transition:font-size .5s cubic-bezier(.2,.7,0,1)}
.exC.on .exBody{left:clamp(26px,2.6vw,44px);bottom:clamp(26px,4vh,44px);right:auto;width:min(30vw,460px)}
.exC.on .exBody h3{font-size:clamp(28px,2.5vw,42px);line-height:1.02;letter-spacing:-.03em}
.exMore{display:grid;grid-template-rows:0fr;opacity:0;transition:grid-template-rows .6s cubic-bezier(.2,.7,0,1),opacity .35s}
.exC.on .exMore{grid-template-rows:1fr;opacity:1;transition:grid-template-rows .6s cubic-bezier(.2,.7,0,1),opacity .5s .25s}
.exMore p{margin:0 0 22px;font-size:16px;line-height:1.5;color:rgba(244,243,239,.75);max-width:36ch}
.exBtn{display:inline-flex;align-items:center;gap:16px;height:52px;padding:0 6px 0 22px;border-radius:999px;border:0;background:linear-gradient(135deg,#F7B583,#E58A50);color:#0B0B0C;font:500 16px 'Onest',sans-serif;cursor:pointer;box-shadow:0 10px 30px rgba(241,158,101,.3);transition:box-shadow .3s,transform .3s;white-space:nowrap}
.exBtn i{display:grid;place-items:center;width:40px;height:40px;border-radius:50%;background:rgba(11,11,12,.88);color:#F7B583}
.exBtn i svg{transition:transform .4s cubic-bezier(.2,.7,0,1)}
.exBtn:hover{box-shadow:0 12px 40px rgba(241,158,101,.5);transform:translateY(-1px)}
.exBtn:hover i svg{transform:rotate(45deg)}
.exBtn:focus-visible{outline:2px solid #FFD9AE;outline-offset:3px}
.exIn{min-height:0;overflow:hidden;display:flex;flex-direction:column;align-items:flex-start}
@media (max-width: 1100px){.exRow{overflow-x:auto;scroll-snap-type:x mandatory;height:auto;padding-bottom:8px}.exC,.exC.on{flex:0 0 min(78vw,420px);height:clamp(420px,62vh,560px);scroll-snap-align:start}.exC::after,.exC.on::after{background:linear-gradient(180deg,rgba(10,10,11,.2) 0%,rgba(10,10,11,.95) 100%)}.exC .exBody,.exC.on .exBody{left:20px;right:20px;bottom:20px;width:auto}.exC .exMore{grid-template-rows:1fr;opacity:1}.exC .exBody h3{font-size:26px}.exBg{filter:none;transform:none}}
@media (max-width: 767px){.exRow{padding:0 16px 8px;scroll-padding-left:16px}}
@media (prefers-reduced-motion: reduce){.exC,.exBg,.exMore,.exBody h3{transition:none}}

.exShort{display:block;white-space:nowrap}
.exFull{display:none}
.exC:not(.on) .exBody h3{font-size:clamp(14px,1.05vw,18px);letter-spacing:-.01em;text-shadow:0 0 18px rgba(0,0,0,.9),0 2px 6px rgba(0,0,0,.8)}
.exC.on .exShort{display:none}
.exC.on .exFull{display:block;max-width:15ch}
